const getWoWLogGroupsByOwner = `-- name: GetWoWLogGroupsByOwner :many
SELECT
  wow_log_groups.id, wow_log_groups.owner, wow_log_groups.created_at, wow_log_groups.updated_at, wow_log_groups.log_type,
  files_agg.files,
  latest_job.output AS processing_output
FROM
  wow_log_groups
    LEFT JOIN LATERAL (
    SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'id', lf.id,
        'owner', lf.owner,
        'wow_log_id', lf.wow_log_id,
        'hash', lf.hash,
        'size_bytes', lf.size_bytes,
        'mime_type', lf.mime_type,
        'compressed_size_bytes', lf.compressed_size_bytes,
        'content_encoding', lf.content_encoding,
        'created_at', lf.created_at,
        'updated_at', lf.updated_at,
        'storage_deleted_at', lf.storage_deleted_at
      )
      ORDER BY lf.created_at) FILTER (WHERE lf.id IS NOT NULL),
      '[]'::jsonb
    )::wow_log_group_files AS files
    FROM log_file lf
    WHERE lf.wow_log_id = wow_log_groups.id
    ) files_agg ON true

    LEFT JOIN LATERAL (
    SELECT rj.metadata->'output' AS output
    FROM river_job rj
    WHERE rj.args ->> 'log_group_id' = wow_log_groups.id::text
    ORDER BY rj.created_at DESC
    LIMIT 1
    ) latest_job ON true
WHERE
  wow_log_groups.owner = $1
  AND (
    $2::timestamptz IS NULL
    OR $3::timestamptz IS NULL
    OR (wow_log_groups.created_at >= $2 AND wow_log_groups.created_at < $3)
    OR EXISTS (
      SELECT 1
      FROM log_instances li
      WHERE li.log_group_id = wow_log_groups.id
        AND li.start_time < $3
        AND li.end_time >= $2
    )
  )
ORDER BY
  wow_log_groups.created_at DESC
`

